import { defineConfig } from "astro/config";
import tailwindcss from "@tailwindcss/vite";
import nimbus, {
  defineConfig as defineNimbusConfig,
} from "@cloudflare/nimbus-docs";
import { tableScroll } from "@cloudflare/nimbus-docs/markdown";

// `review-kit site build` (review_kit/site.py) sets these; the page content
// under src/content/docs is generated by it as well and is not committed.
const env = (name: string, fallback: string) => process.env[name] || fallback;

const nimbusConfig = defineNimbusConfig({
  // Canonical origin: drives canonical URLs, OG image URLs, robots.txt,
  // the sitemap and the links in /llms.txt.
  // The builder passes the custom domain from wrangler.jsonc.
  site: env("REVIEW_SITE_URL", "http://localhost"),
  title: env("REVIEW_SITE_TITLE", "Review snapshot"),
  description: env("REVIEW_SITE_DESCRIPTION", "hk·GitHub·git 스냅샷"),
  locale: "ko",
  socialImageAlt: "review snapshot",
  sidebar: {
    items: ["index", { autogenerate: { collection: "docs" } }],
  },
});

export default defineConfig({
  output: "static",
  // Tailwind v4 via its Vite plugin (the PostCSS plugin doesn't build under
  // Astro 7's Vite 8 bundler).
  vite: {
    plugins: [tailwindcss()],
  },
  prefetch: {
    prefetchAll: true,
    defaultStrategy: "hover",
  },
  integrations: [
    nimbus(nimbusConfig, {
      rules: {
        "nimbus/frontmatter-shape": "error",
        "nimbus/internal-link": "error",
      },
      markdown: {
        hastPlugins: [tableScroll()],
        // headingAttributes stays off: generated pages carry agent-written
        // headings, and `{…}` at the end of one would be read as attributes.
        features: { headingAttributes: false },
      },
    }),
  ],
});
